import os
import google.cloud.speech_v1p1beta1 as speech

def partial_results(payload, config=None):
    config = config or {}
    client = speech.SpeechClient(**config)
    streaming_config = {
        "config": {
            "encoding": "LINEAR16",
            "sample_rate_hertz": 16000,
            "language_code": "en-US",
        },
        "interim_results": True,
    }
    streaming_client = client.streaming_recognition(streaming_config)
    for chunk in payload:
        request = speech.StreamingRecognizeRequest(audio_content=chunk)
        response = streaming_client.stream(streaming_client.stream(request))
        for result in response:
            if result.results:
                yield result.results[0].alternatives[0].transcript

